    @Override
    @Transactional(readOnly = true)
    public Integer findPossibleDuplicateOf(Owner owner) throws DataAccessException {
        String soundex = Soundex.of(owner.getLastName());
        if (soundex.isEmpty() || owner.getPostcode() == null) {
            return null;
        }
        String identityKey = owner.getIdentityKey();
        return ownerRepository.findAll().stream()
            .filter(existing -> !existing.getId().equals(owner.getId())
                && !existing.isDeleted()
                && owner.getPostcode().equals(existing.getPostcode())
                && soundex.equals(Soundex.of(existing.getLastName()))
                && !identityKey.equals(existing.getIdentityKey()))
            .map(Owner::getId)
            .min(Integer::compare)
            .orElse(null);
    }

    @Override
    @Transactional(readOnly = true)
    public long countOwnersInCity(String city) throws DataAccessException {
        return ownerRepository.countByCityIgnoringCase(lowerCase(city));
    }

    @Override
    @Transactional(readOnly = true)
    public long countOwnersRegisteredOn(LocalDate registrationDate) throws DataAccessException {
        return ownerRepository.countByRegistrationDate(registrationDate);
    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Owner> findHouseholdMembers(Owner owner) throws DataAccessException {
        String householdId = householdIdOf(owner);
        if (householdId == null) {
            return List.of();
        }
        return ownerRepository.findByLastNameIgnoringCase(lowerCase(owner.getLastName())).stream()
            .filter(existing -> !existing.getId().equals(owner.getId())
                && !existing.isDeleted()
                && householdId.equals(existing.getHouseholdId()))
            .toList();
    }

    @Override
    public String householdIdOf(Owner owner) {
        if (owner.getLastName() == null || owner.getPostcode() == null) {
            return null;
        }
        return sha256Hex(normalizeForComparison(owner.getLastName()) + "|" + owner.getPostcode()).substring(0, 12);
    }

    /** Trims the value, collapses runs of whitespace into a single space and lower-cases it. */
    private static String normalizeForComparison(String value) {
        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    private static String lowerCase(String value) {
        return value == null ? null : value.toLowerCase(Locale.ROOT);
    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
        return ownerRepository.findByLastName(lastName);
    }

    @Override
    @Transactional(readOnly = true)
    public Collection<Visit> findVisitsByPetId(int petId) {
        return visitRepository.findByPetId(petId);
    }

    @Override
    @Transactional(readOnly = true)
    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
    }

    /**
     * De-duplicates a computed member id: returns it unchanged when no existing owner has it, otherwise
     * appends '-&lt;n&gt;' with the smallest n &gt;= 2 that makes it unique.
     */
    private String uniqueMemberId(String memberId) {
        if (ownerRepository.countByMemberId(memberId) == 0) {
            return memberId;
        }
        int n = 2;
        while (ownerRepository.countByMemberId(memberId + "-" + n) > 0) {
            n++;
        }
        return memberId + "-" + n;
    }

    /**
     * Builds a member id '&lt;REGION&gt;&lt;FY&gt;&lt;HASH8&gt;&lt;CHK&gt;' (see {@link MemberIds}): the region derived
     * from the postcode (see {@link OwnerPostcode#regionOf(String, String)}), the two-digit fiscal year of the
     * registration date (today when absent), the first 8 upper-case hex characters of the SHA-256 of the
     * UTF-8 bytes of the normalized telephone followed by the last name, and the Luhn check digit.
     */
    private static String memberId(Owner owner) {
        String region = OwnerPostcode.regionOf(owner.getPostcode(), owner.getCity());
        LocalDate registrationDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
        return MemberIds.of(region, registrationDate,
            sha256Hex(telephone + lastName).substring(0, 8).toUpperCase(Locale.ROOT));
    }

    private static String sha256Hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(digest);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 is not available", e);
        }
    }

    private <T> T findEntityById(Supplier<T> supplier) {
        try {
            return supplier.get();
        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
            // Just ignore not found exceptions for Jdbc/Jpa realization
            return null;
        }
    }

