package org.springframework.samples.petclinic.acceptance;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

/** identity-v2: the identifiers are derived from the version-2 region code 'V2&lt;REGION&gt;', while
 * 'locality', 'timezone' and 'ownerSegment' keep using the plain region; the audit event carries
 * schemaVersion 2. */
class IdentityV2AcceptanceTest extends AcceptanceBase {

	@Test
	void identifiersUseVersionTwoRegionCode() throws Exception {
		ObjectNode body = knownOwner("Sydney");
		JsonNode owner = fetchOwner(createOwnerOk(body));
		String telephone = owner.get("telephone").asText();
		String lastName = body.get("lastName").asText();
		String fy = owner.get("fiscalYear").asText().substring(2);

		String memberBody = "V2NSW" + fy + shaHex(telephone + lastName, 8);
		JsonNode identity = owner.get("identity");
		assertThat(identity.get("memberId").asText()).isEqualTo(memberBody + luhn(memberBody));
		assertThat(identity.get("householdId").asText())
				.isEqualTo(sha256hex("V2NSW|" + lastName.toLowerCase() + "|2000").substring(0, 12));
		assertThat(identity.get("identityKey").asText())
				.isEqualTo(sha256hex("V2NSW|" + telephone + "||" + soundex(lastName)));
	}

	@Test
	void versionOneValuesAreNotProduced() throws Exception {
		ObjectNode body = knownOwner("Sydney");
		JsonNode owner = fetchOwner(createOwnerOk(body));
		String telephone = owner.get("telephone").asText();
		String lastName = body.get("lastName").asText();
		String fy = owner.get("fiscalYear").asText().substring(2);

		String v1MemberBody = "NSW" + fy + shaHex(telephone + lastName, 8);
		JsonNode identity = owner.get("identity");
		assertThat(identity.get("memberId").asText()).isNotEqualTo(v1MemberBody + luhn(v1MemberBody));
		assertThat(identity.get("householdId").asText())
				.isNotEqualTo(sha256hex(lastName.toLowerCase() + "|2000").substring(0, 12));
		assertThat(identity.get("identityKey").asText())
				.isNotEqualTo(sha256hex(telephone + "||" + soundex(lastName)));
	}

	@Test
	void userFacingRegionFieldsStayPlain() throws Exception {
		JsonNode owner = fetchOwner(createOwnerOk(knownOwner("Melbourne")));
		assertThat(owner.get("identity").get("memberId").asText()).startsWith("V2VIC");
		assertThat(owner.get("locality").asText()).isEqualTo("VIC");
		assertThat(owner.get("timezone").asText()).isEqualTo("Australia/Melbourne");
		assertThat(owner.get("ownerSegment").asText()).isEqualTo("STANDARD_METRO");

		JsonNode unknown = fetchOwner(createOwnerOk(ownerNode()));
		assertThat(unknown.get("identity").get("memberId").asText()).startsWith("V2UNKNOWN");
		assertThat(unknown.get("locality").asText()).isEqualTo("UNKNOWN");
		assertThat(unknown.get("ownerSegment").asText()).isEqualTo("STANDARD_REGIONAL");
	}

	@Test
	void duplicateIdentityStillRejected() throws Exception {
		ObjectNode body = knownOwner("Sydney");
		createOwnerOk(body);
		createOwner(body).andExpect(
				org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isConflict());
	}

	@Test
	void auditEventHasSchemaVersionTwo() throws Exception {
		try (AuditLogCapture audit = new AuditLogCapture()) {
			JsonNode owner = fetchOwner(createOwnerOk(knownOwner("Brisbane")));
			String memberId = owner.get("identity").get("memberId").asText();
			JsonNode event = audit.messages().stream()
					.filter(m -> m.startsWith("{"))
					.map(om::readTree)
					.filter(n -> "OWNER_CREATED".equals(n.path("event").asText()))
					.reduce((first, second) -> second)
					.orElseThrow();
			assertThat(event.get("schemaVersion").asInt()).isEqualTo(2);
			assertThat(event.get("memberId").asText()).isEqualTo(memberId).startsWith("V2QLD");
		}
	}

	/** American Soundex, as stated in the identity key spec. */
	private static String soundex(String name) {
		String codes = "01230120022455012623010202";
		String s = name.toUpperCase();
		StringBuilder out = new StringBuilder().append(s.charAt(0));
		char last = codes.charAt(s.charAt(0) - 'A');
		for (int i = 1; i < s.length() && out.length() < 4; i++) {
			char c = s.charAt(i);
			char code = codes.charAt(c - 'A');
			if (code != '0' && code != last) {
				out.append(code);
			}
			if (c != 'H' && c != 'W') {
				last = code;
			}
		}
		while (out.length() < 4) {
			out.append('0');
		}
		return out.toString();
	}
}

